216	  let lowest = Infinity;
217	  let lowestLoc = null;
218	  for (const locKey of Object.keys(LOCATIONS)) {
219	    const prices = state.trade.goodsPrices[locKey] || {};
220	    const price = prices[goodId];
221	    if (price && price < lowest) {
222	      lowest = price;
223	      lowestLoc = locKey;
224	    }
225	  }
226	  return { price: lowest, location: lowestLoc };
227	}
