229	/** 获取某商品在所有地点的最高价格 */
230	function getHighestPrice(goodId) {
231	  const state = StateManager.getState();
232	  let highest = 0;
233	  let highestLoc = null;
234	  for (const locKey of Object.keys(LOCATIONS)) {
235	    const prices = state.trade.goodsPrices[locKey] || {};
236	    const price = prices[goodId];
237	    if (price && price > highest) {
238	      highest = price;
239	      highestLoc = locKey;
240	    }
241	  }
242	  return { price: highest, location: highestLoc };
243	}
244	
245	/** 估算平均买入价 */
