251	/** 更新所有地点所有商品的价格（每3天调用一次） */
252	function updateAllPrices(state) {
253	  for (const locKey of Object.keys(LOCATIONS)) {
254	    const loc = LOCATIONS[locKey];
255	    // 确保价格对象存在
256	    if (!state.trade.goodsPrices[locKey]) {
257	      state.trade.goodsPrices[locKey] = {};
258	    }
259	    for (const good of GOODS) {
260	      let price = good.basePrice;
261	
262	      // 1. 地点倍率
263	      if (loc.priceMod && loc.priceMod[good.id]) {
264	        price *= loc.priceMod[good.id];
265	      }
266	
267	      // 2. 随机波动 ±25%
268	      const fluctuation = 0.75 + Math.random() * 0.5;
269	      price *= fluctuation;
270	
271	      // 3. 均值回归（10%向旧价格靠拢）
272	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
273	      price = price + (oldPrice - price) * 0.1;
274	
275	      // 4. 限制在合理范围
276	      price = Math.max(
277	        good.basePrice * 0.25,
278	        Math.min(good.basePrice * 6, price),
279	      );
280	      price = Math.round(price * 100) / 100;
281	
282	      state.trade.goodsPrices[locKey][good.id] = price;
283	    }
284	  }
285	  state.trade.lastPriceUpdate = state.player.day;
286	}
