107	
108	  // 加钱
109	  state.resources.cash += totalEarned;
110	  state.resources.totalEarned += totalEarned;
111	
112	  // 从背包移除
113	  existing.qty -= qty;
114	  if (existing.qty <= 0) {
115	    state.inventory.items = state.inventory.items.filter(
116	      (i) => i.id !== goodId,
117	    );
118	  }
119	
120	  // 低买高卖时显示利润
121	  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
122	  let profitMsg = "";
123	  if (sameLocationPenalty) {
124	    profitMsg = " ⚠️ 同地转卖，贬值严重！";
125	  } else if (buyPrice > 0) {
126	    const profit = totalEarned - buyPrice * qty;
127	    if (profit > 0) {
128	      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
129	    } else if (profit < 0) {
130	      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
131	    }
132	  }
133	
134	  // 卖出后该商品在当地降价 1~3%
135	  const sellDelta = -(0.01 + Math.random() * 0.02);
136	  adjustPriceAfterTrade(locKey, goodId, sellDelta);
137	  const newPrice = getCurrentPrice(locKey, goodId);
