148	/** 批发进货（批发市场专属） */
149	function buyWholesale(goodId, qty) {
150	  const state = StateManager.getState();
151	  const good = getGoodById(goodId);
152	  if (!good) {
153	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
154	    return false;
155	  }
156	
157	  const locKey = state.trade.currentLocation;
158	  var price = getCurrentPrice(locKey, goodId);
159	
160	  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打7折
161	  var sameLocationPenalty = false;
162	  if (existing.boughtAt === locKey) {
163	    price = Math.round(price * 0.7 * 100) / 100;
164	    sameLocationPenalty = true;
165	  }
166	
167	  // 批发折扣：批发市场的价格 × 0.7（批量价）
168	  const wholesalePrice = Math.round(price * 0.7 * 100) / 100;
169	  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;
170	
171	  // 最低起批量
172	  if (qty < 5) {
173	    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
174	    return false;
175	  }
176	
177	  // 检查现金
178	  if (state.resources.cash < totalCost) {
179	    StateManager.addMessage(
180	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
181	      "danger",
182	    );
183	    return false;
184	  }
185	
186	  // 检查背包
187	  const currentItems = state.inventory.items.reduce(
188	    (sum, item) => sum + item.qty,
189	    0,
190	  );
191	  if (currentItems + qty > state.inventory.capacity) {
192	    StateManager.addMessage(
193	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
194	      "danger",
195	    );
196	    return false;
197	  }
198	
199	  // 扣钱
200	  state.resources.cash -= totalCost;
201	
202	  // 记录买入价（用于后续利润计算）
203	  const existing = state.inventory.items.find((i) => i.id === goodId);
204	  if (existing) {
205	    // 加权平均买入价
206	    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
207	    const newTotal = wholesalePrice * qty;
208	    existing.qty += qty;
209	    existing.boughtAt = locKey;
210	    existing.avgBuyPrice =
211	      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
212	  } else {
213	    state.inventory.items.push({
214	      id: goodId,
215	      qty,
216	      avgBuyPrice: wholesalePrice,
217	      boughtAt: locKey,
218	    });
219	  }
220	
221	  StateManager.addMessage(
222	    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
223	    "success",
224	  );
225	  return true;
226	}
227	
228	/** 快速出售（从背包里选一个商品卖） */
229	function quickSell(goodId) {
230	  const state = StateManager.getState();
231	  const existing = state.inventory.items.find((i) => i.id === goodId);
232	  if (!existing || existing.qty <= 0) {
233	    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
234	    return false;
235	  }
236	  const qty = Math.min(existing.qty, 1); // 默认卖1个
237	  return sellGood(goodId, qty);
238	}
239	
240	/** 交易后动态调价：买入涨价，卖出降价 */
241	function adjustPriceAfterTrade(locKey, goodId, delta) {
242	  const state = StateManager.getState();
243	  const good = getGoodById(goodId);
244	  if (!good) return;
245	  const prices = state.trade.goodsPrices[locKey];
246	  if (!prices) return;
247	  const oldPrice = prices[goodId] || good.basePrice;
248	  const change = oldPrice * delta;
249	  let newPrice = oldPrice + change;
250	  // 限制范围
251	  newPrice = Math.max(
252	    good.basePrice * 0.3,
253	    Math.min(good.basePrice * 5, newPrice),
254	  );
255	  newPrice = Math.round(newPrice * 100) / 100;
256	  prices[goodId] = newPrice;
257	}
258	
259	/** 获取当前地点某商品的零售价 */
260	function getCurrentPrice(locKey, goodId) {
261	  const state = StateManager.getState();
262	  const prices = state.trade.goodsPrices[locKey];
263	  if (prices && prices[goodId] !== undefined) {
264	    return prices[goodId];
265	  }
266	  const good = getGoodById(goodId);
267	  return good ? good.basePrice : 1;
268	}
269	
270	/** 获取某商品在所有地点的最低价格（用于价格对比） */
271	function getLowestPrice(goodId) {
272	  const state = StateManager.getState();
273	  let lowest = Infinity;
274	  let lowestLoc = null;
275	  for (const locKey of Object.keys(LOCATIONS)) {
276	    const prices = state.trade.goodsPrices[locKey] || {};
277	    const price = prices[goodId];
278	    if (price && price < lowest) {
279	      lowest = price;
280	      lowestLoc = locKey;
281	    }
282	  }
283	  return { price: lowest, location: lowestLoc };
284	}
285	
286	/** 获取某商品在所有地点的最高价格 */
287	function getHighestPrice(goodId) {
288	  const state = StateManager.getState();
289	  let highest = 0;
290	  let highestLoc = null;
291	  for (const locKey of Object.keys(LOCATIONS)) {
292	    const prices = state.trade.goodsPrices[locKey] || {};
293	    const price = prices[goodId];
294	    if (price && price > highest) {
295	      highest = price;
296	      highestLoc = locKey;
297	    }
298	  }
299	  return { price: highest, location: highestLoc };
300	}
301	
302	/** 估算平均买入价 */
303	function getAvgBuyPrice(state, goodId) {
304	  const item = state.inventory.items.find((i) => i.id === goodId);
305	  return item ? item.avgBuyPrice || 0 : 0;
306	}
307	
308	/** 更新所有地点所有商品的价格（每3天调用一次） */
309	function updateAllPrices(state) {
310	  for (const locKey of Object.keys(LOCATIONS)) {
311	    const loc = LOCATIONS[locKey];
312	    // 确保价格对象存在
313	    if (!state.trade.goodsPrices[locKey]) {
314	      state.trade.goodsPrices[locKey] = {};
315	    }
316	    for (const good of GOODS) {
317	      let price = good.basePrice;
318	
319	      // 1. 地点倍率
320	      if (loc.priceMod && loc.priceMod[good.id]) {
321	        price *= loc.priceMod[good.id];
322	      }
323	
324	      // 2. 随机波动 ±25%
325	      const fluctuation = 0.75 + Math.random() * 0.5;
326	      price *= fluctuation;
327	
328	      // 3. 均值回归（10%向旧价格靠拢）
329	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
330	      price = price + (oldPrice - price) * 0.1;
331	
332	      // 4. 限制在合理范围
333	      price = Math.max(
334	        good.basePrice * 0.25,
335	        Math.min(good.basePrice * 6, price),
336	      );
337	      price = Math.round(price * 100) / 100;
338	
339	      state.trade.goodsPrices[locKey][good.id] = price;
340	    }
341	  }
342	  state.trade.lastPriceUpdate = state.player.day;
343	}
