214	/** 快速出售（从背包里选一个商品卖） */
215	function quickSell(goodId) {
216	  const state = StateManager.getState();
217	  const existing = state.inventory.items.find((i) => i.id === goodId);
218	  if (!existing || existing.qty <= 0) {
219	    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
220	    return false;
221	  }
222	  const qty = Math.min(existing.qty, 1); // 默认卖1个
223	  return sellGood(goodId, qty);
224	}
