226	/** 交易后动态调价：买入涨价，卖出降价 */
227	function adjustPriceAfterTrade(locKey, goodId, delta) {
228	  const state = StateManager.getState();
229	  const good = getGoodById(goodId);
230	  if (!good) return;
231	  const prices = state.trade.goodsPrices[locKey];
232	  if (!prices) return;
233	  const oldPrice = prices[goodId] || good.basePrice;
234	  const change = oldPrice * delta;
235	  let newPrice = oldPrice + change;
236	  // 限制范围
237	  newPrice = Math.max(
238	    good.basePrice * 0.3,
239	    Math.min(good.basePrice * 5, newPrice),
240	  );
241	  newPrice = Math.round(newPrice * 100) / 100;
242	  prices[goodId] = newPrice;
243	}
