294	/** 更新所有地点所有商品的价格（每3天调用一次） */
295	function updateAllPrices(state) {
296	  for (const locKey of Object.keys(LOCATIONS)) {
297	    const loc = LOCATIONS[locKey];
298	    // 确保价格对象存在
299	    if (!state.trade.goodsPrices[locKey]) {
300	      state.trade.goodsPrices[locKey] = {};
301	    }
302	    for (const good of GOODS) {
303	      let price = good.basePrice;
304	
305	      // 1. 地点倍率
306	      if (loc.priceMod && loc.priceMod[good.id]) {
307	        price *= loc.priceMod[good.id];
308	      }
309	
310	      // 2. 随机波动 ±25%
311	      const fluctuation = 0.75 + Math.random() * 0.5;
312	      price *= fluctuation;
313	
314	      // 3. 均值回归（10%向旧价格靠拢）
315	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
316	      price = price + (oldPrice - price) * 0.1;
317	
318	      // 4. 限制在合理范围
319	      price = Math.max(
320	        good.basePrice * 0.25,
321	        Math.min(good.basePrice * 6, price),
322	      );
323	      price = Math.round(price * 100) / 100;
324	
325	      state.trade.goodsPrices[locKey][good.id] = price;
326	    }
327	  }
328	  state.trade.lastPriceUpdate = state.player.day;
329	}
